<?php
use CodeIgniter\Test\CIUnitTestCase;use CodeIgniter\Test\FeatureTestTrait;
/** @internal */final class AdminAuditRootTest extends CIUnitTestCase{use FeatureTestTrait;protected function setUp():void{parent::setUp();$this->db=db_connect();$f=Config\Database::forge('tests');foreach(['audit_logs','users']as$t)$f->dropTable($t,true);$this->t($f,'users',['username'=>['type'=>'VARCHAR','constraint'=>50],'email'=>['type'=>'VARCHAR','constraint'=>200,'null'=>true],'full_name'=>['type'=>'VARCHAR','constraint'=>200],'password_hash'=>['type'=>'VARCHAR','constraint'=>255],'role'=>['type'=>'VARCHAR','constraint'=>20],'is_active'=>['type'=>'INTEGER'],'last_login_at'=>['type'=>'DATETIME','null'=>true],'created_at'=>['type'=>'DATETIME','null'=>true],'updated_at'=>['type'=>'DATETIME','null'=>true]]);$this->t($f,'audit_logs',['user_id'=>['type'=>'INTEGER','null'=>true],'action'=>['type'=>'VARCHAR','constraint'=>100],'entity_type'=>['type'=>'VARCHAR','constraint'=>100],'entity_id'=>['type'=>'INTEGER','null'=>true],'old_values'=>['type'=>'TEXT','null'=>true],'new_values'=>['type'=>'TEXT','null'=>true],'ip_address'=>['type'=>'VARCHAR','constraint'=>45,'null'=>true],'created_at'=>['type'=>'DATETIME','null'=>true]]);}
 protected function tearDown():void{$f=Config\Database::forge('tests');foreach(['audit_logs','users']as$t)$f->dropTable($t,true);parent::tearDown();}public function testGuestRootRedirectsToLogin():void{$this->get('/')->assertRedirectTo(site_url('login'));}public function testAuthenticatedRootShowsDashboard():void{$r=$this->admin()->get('/');$r->assertStatus(200);$this->assertStringContainsString('Kelola keuangan akademik',$r->getBody());}public function testAdminCreateAndAuditRead():void{$r=$this->mut()->post('/pengaturan/admin/post',['username'=>'operator','full_name'=>'Operator Keuangan','email'=>'operator@example.test','password'=>'rahasia123','is_active'=>true]);$r->assertStatus(201);$this->assertTrue(password_verify('rahasia123',$this->db->table('users')->where('username','operator')->get()->getRow('password_hash')));$page=$this->admin()->get('/audit-log');$page->assertStatus(200);$this->assertStringContainsString('auditLogController',$page->getBody());$data=$this->admin()->get('/audit-log/read');$data->assertStatus(200);$this->assertSame('ADMIN_USER_CREATED',json_decode((string)$data->getJSON(),true)['data']['logs'][0]['action']);}private function t($f,$n,$x):void{$f->addField(array_merge(['id'=>['type'=>'INTEGER','auto_increment'=>true]],$x));$f->addKey('id',true);$f->createTable($n);}private function admin():self{return$this->withSession(['auth'=>['id'=>1,'role'=>'ADMIN','username'=>'admin','full_name'=>'Admin']]);}private function mut():self{helper('form');return$this->admin()->withHeaders([config('Security')->headerName=>csrf_hash()])->withBodyFormat('json');}}
